package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
public class ReadyWaitServiceTest {
 @Test public void unknownOrMissingCommandsCannotBeReady(){var out=ReadyWaitService.evaluate(Map.of("services","ready","project","P","model",Map.of("state","UNKNOWN")),List.of("a"),List.of("b"),"equal",false);assertEquals(false,out.get("ready"));assertEquals(List.of("b"),out.get("missing_tools"));assertTrue(((List<?>)out.get("blockers")).contains("database_equal_not_verified"));}
 @Test public void databaseRequirementsAreExplicit(){var seen=Map.<String,Object>of("services","ready","project","P","model",Map.of("state","READY"),"database",Map.of("uuid","b","connected",true,"equality","NOT_EQUAL","configuration_synchronized",false));assertEquals(false,ReadyWaitService.evaluate(seen,List.of(),List.of(),"connected",false).get("ready"));assertEquals(false,ReadyWaitService.evaluate(seen,List.of(),List.of(),"equal",false).get("ready"));assertThrows(IllegalArgumentException.class,()->ReadyWaitService.evaluate(Map.of("services","ready"),List.of(),List.of(),"bound",false));}
 @Test public void zeroTimeoutObservesOnceAndNeverClaimsSuccess()throws Exception{var calls=new AtomicInteger();var out=ReadyWaitService.await(()->{calls.incrementAndGet();return Map.of("ready",false);},0);assertEquals(1,calls.get());assertEquals(true,out.get("timed_out"));assertEquals(true,out.get("observation_only"));}
 @Test public void waitEndsWhenReadyAndNoFurtherProbes()throws Exception{var calls=new AtomicInteger();var out=ReadyWaitService.await(()->Map.of("ready",calls.incrementAndGet()==2),2000);assertEquals(true,out.get("ready"));assertEquals(false,out.get("timed_out"));assertEquals(2,calls.get());}
 @Test public void connectedRequiresExplicitPerBaseProof(){var seen=new LinkedHashMap<String,Object>(Map.of("services","ready","project","P","model",Map.of("state","READY"),"database",Map.of("connected",true,"connected_verified",false)));assertEquals(false,ReadyWaitService.evaluate(seen,List.of(),List.of(),"connected",false).get("ready"));seen.put("database",Map.of("connected_verified",true));assertEquals(true,ReadyWaitService.evaluate(seen,List.of(),List.of(),"connected",false).get("ready"));}
 @Test public void selectedProjectReadinessDoesNotScanUnrelatedProjectStates(){var gateway=new com.codepilot1c.core.edt.metadata.EdtMetadataGateway(){public void ensureWorkspaceRuntimeAvailable(){}public void ensureEdtServicesAvailable(){}public void ensureMetadataReadCapability(){}};var global=new com.codepilot1c.core.mcp.host.McpSemanticReadinessProbe(gateway,()->true,()->List.of(new com.codepilot1c.core.mcp.host.ProjectReadiness("Unrelated","building"))).evaluate();assertFalse(global.ready());var services=com.codepilot1c.core.tools.development.EdtReadyTool.globalServices(gateway,()->true);assertTrue(services.ready());assertTrue(services.projects().isEmpty());assertEquals(true,ReadyWaitService.evaluate(Map.of("services",services.services(),"project","Chosen","model",Map.of("state","READY")),List.of(),List.of(),"none",false).get("ready"));}
}
